<?php
require_once dirname(__DIR__).'/app/helpers.php';require_auth();require_once dirname(__DIR__).'/app/Services/CardService.php';$svc=new CardService(Database::connection());$uid=(int)auth_user()['id'];$error=null;$success=null;$ref=null;$cards=$svc->list($uid);if($_SERVER['REQUEST_METHOD']==='POST'){try{verify_csrf();$ref=$svc->pay($uid,(int)$_POST['card_id'],trim($_POST['amount']),trim($_POST['pin']),trim($_POST['merchant']),$_POST['channel']??'online',trim($_POST['idempotency_key']??'')?:null);$success='Card payment completed. Reference: '.$ref;}catch(Throwable $e){$error=$e->getMessage();}}?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Card Payment</title><link href="https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/css/bootstrap.min.css" rel="stylesheet"></head><body><div class="container py-5" style="max-width:760px"><div class="d-flex justify-content-between mb-4"><h2>Simulated Card Payment</h2><a href="/commserve/public/cards.php">Cards</a></div><div class="alert alert-warning">Demo-only POS/online card transaction. No real payment network is contacted.</div><?php if($error):?><div class="alert alert-danger"><?=e($error)?></div><?php endif;?><?php if($success):?><div class="alert alert-success"><?=e($success)?></div><?php endif;?><div class="card border-0 shadow-sm"><div class="card-body"><form method="post" class="row g-3"><?=csrf_field()?><div class="col-12"><label class="form-label">Card</label><select name="card_id" class="form-select" required><?php foreach($cards as $c):?><option value="<?=$c['id']?>">•••• <?=e($c['last4'])?> — <?=e($c['status'])?> — <?=e($c['account_number'])?></option><?php endforeach;?></select></div><div class="col-md-6"><label class="form-label">Merchant</label><input name="merchant" class="form-control" placeholder="Demo Store" required></div><div class="col-md-3"><label class="form-label">Amount</label><input name="amount" class="form-control" inputmode="decimal" required></div><div class="col-md-3"><label class="form-label">Channel</label><select name="channel" class="form-select"><option value="online">Online</option><option value="pos">POS</option></select></div><div class="col-md-6"><label class="form-label">Card PIN</label><input name="pin" type="password" class="form-control" maxlength="6" required></div><div class="col-md-6"><label class="form-label">Idempotency key</label><input name="idempotency_key" class="form-control" value="<?=e('CARD-'.bin2hex(random_bytes(6)))?>" required></div><div class="col-12"><button class="btn btn-primary">Pay with simulated card</button></div></form></div></div></div></body></html>
